import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDocumentStore } from './src/document-store.js';

const store = createDocumentStore({ a: 'old', b: 'target', c: 'conflict' });
const renders = [];
const handoffs = [];
const workspace = createWorkspace({ store, renderDocument: value => renders.push(value), onHandoff: (departure, navigation) => {
  handoffs.push(departure);
  if (departure.id === 'a') navigation.open('c');
} });
workspace.open('a');
workspace.edit('edited');
workspace.open('b');
assert.deepEqual(handoffs, [{ id: 'a', text: 'edited' }]);
assert.deepEqual(renders.at(-1), { id: 'c', text: 'conflict' });
assert.equal(store.read('a'), 'edited');
workspace.dispose();
assert.equal(handoffs.length, 1);

const closeStore = createDocumentStore({ x: 'text' });
const closeHandoffs = [];
const closing = createWorkspace({ store: closeStore, renderDocument() {}, onHandoff: departure => closeHandoffs.push(departure) });
closing.open('x');
closing.close();
assert.deepEqual(closeHandoffs, [{ id: 'x', text: 'text' }]);
console.log('handoff, redirect, text, close, and dispose checks passed');
EOF"

